/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempt = 0;
    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= config.max_attempts => {
                return Err(error)
            }
            Err(error) => {
                let retry_number = attempt;
                sleeper.sleep_ms(config.delay_for_retry(retry_number));
                let _ = error;
            }
        }
    }
}

