#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig { max_attempts, base_delay_ms, max_delay_ms }
    }

    #[test]
    fn retries_transient_errors_with_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4, 10, 100), &mut sleeper, || {
            calls += 1;
            if calls < 4 { Err(RetryError::Transient("temporary".into())) } else { Ok(()) }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 40]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn delay_saturates_without_overflow() {
        let policy = config(u32::MAX, u64::MAX, 500);
        assert_eq!(policy.delay_for_retry(1), 500);
        assert_eq!(policy.delay_for_retry(100), 500);
    }
}

